mapper.select:
SELECT i.id item_id,r.type,coalesce(jsonb_array_length(r.content_data::jsonb->'blanks'),0) blank_count,
    coalesce((SELECT jsonb_agg(o.option_key ORDER BY o.sort_order)::text FROM question_option o WHERE o.revision_id=r.id),'[]') option_keys
    FROM practice_item i JOIN question_revision r ON r.id=i.revision_id WHERE i.session_id=#{id} AND i.id IN #{itemId}
